using Identity.Application;
using Identity.Contracts;
using Identity.Domain;
using Microsoft.EntityFrameworkCore;

namespace Identity.Persistence.KeyManagement;

public sealed class SigningKeyEntity
{
    public string Kid { get; set; } = "";
    public string Realm { get; set; } = "";
    public int Size { get; set; }
    public string PublicPemFingerprint { get; set; } = "";
    public string VaultPath { get; set; } = "";
    public int VaultVersion { get; set; }
    public string State { get; set; } = "";
    public DateTimeOffset CreatedAt { get; set; }
    public string? KeycloakComponentId { get; set; }
    public DateTimeOffset? ActivatedAt { get; set; }
    public DateTimeOffset? PassivatedAt { get; set; }
    public DateTimeOffset? RetiredAt { get; set; }
    public DateTimeOffset? DestroyedAt { get; set; }
    public string? Origin { get; set; }
}

public sealed class KeyHistoryEntity
{
    public int Id { get; set; }
    public string Realm { get; set; } = "";
    public string Kid { get; set; } = "";
    public string FromState { get; set; } = "";
    public string ToState { get; set; } = "";
    public DateTimeOffset OccurredAt { get; set; }
    public string Actor { get; set; } = "";
    public string? Reason { get; set; }
}

public sealed class RotationOperationEntity
{
    public string OperationId { get; set; } = "";
    public string IdempotencyKey { get; set; } = "";
    public string Realm { get; set; } = "";
    public string? TargetKid { get; set; }
    public string? PreviousKid { get; set; }
    public string CurrentStep { get; set; } = "";
    public string Status { get; set; } = "";
    public DateTimeOffset StartedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; }
    public string Actor { get; set; } = "";
    public string? FailureReason { get; set; }
    public string? LockOwnerToken { get; set; }
}

public sealed class ScopeDefinitionEntity
{
    public Guid Id { get; set; }
    public string Key { get; set; } = "";
    public string DisplayName { get; set; } = "";
    public string? Description { get; set; }
    public bool IsActive { get; set; } = true;
    public string ValueType { get; set; } = "String";
    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; }
}

public sealed class ApplicationResourceEntity
{
    public Guid Id { get; set; }
    public string Key { get; set; } = "";
    public string DisplayName { get; set; } = "";
    public string? Description { get; set; }
}

public sealed class ScopeResourceMappingEntity
{
    public Guid ScopeDefinitionId { get; set; }
    public Guid ApplicationResourceId { get; set; }
}

public sealed class RoleAllowedScopeEntity
{
    public string RoleName { get; set; } = "";
    public Guid ScopeDefinitionId { get; set; }
}

public sealed class UserRoleAssignmentEntity
{
    public Guid Id { get; set; }
    public string UserId { get; set; } = "";
    public string RoleName { get; set; } = "";
    public DateTimeOffset AssignedAt { get; set; }
}

public sealed class AssignmentScopeEntity
{
    public Guid Id { get; set; }
    public Guid UserRoleAssignmentId { get; set; }
    public Guid ScopeDefinitionId { get; set; }
}

public sealed class AssignmentScopeValueEntity
{
    public Guid Id { get; set; }
    public Guid AssignmentScopeId { get; set; }
    public string Value { get; set; } = "";
}

public sealed class KeyMetadataDbContext(DbContextOptions<KeyMetadataDbContext> options) : DbContext(options)
{
    public DbSet<SigningKeyEntity> SigningKeys => Set<SigningKeyEntity>();
    public DbSet<KeyHistoryEntity> KeyHistories => Set<KeyHistoryEntity>();
    public DbSet<RotationOperationEntity> RotationOperations => Set<RotationOperationEntity>();
    public DbSet<ScopeDefinitionEntity> ScopeDefinitions => Set<ScopeDefinitionEntity>();
    public DbSet<ApplicationResourceEntity> ApplicationResources => Set<ApplicationResourceEntity>();
    public DbSet<ScopeResourceMappingEntity> ScopeResourceMappings => Set<ScopeResourceMappingEntity>();
    public DbSet<RoleAllowedScopeEntity> RoleAllowedScopes => Set<RoleAllowedScopeEntity>();
    public DbSet<UserRoleAssignmentEntity> UserRoleAssignments => Set<UserRoleAssignmentEntity>();
    public DbSet<AssignmentScopeEntity> AssignmentScopes => Set<AssignmentScopeEntity>();
    public DbSet<AssignmentScopeValueEntity> AssignmentScopeValues => Set<AssignmentScopeValueEntity>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<SigningKeyEntity>(e =>
        {
            e.HasKey(x => new { x.Realm, x.Kid });
            e.HasIndex(x => x.Kid).IsUnique(false);
            e.Property(x => x.State).HasMaxLength(32).IsRequired();
            e.Property(x => x.PublicPemFingerprint).HasMaxLength(128).IsRequired();
            e.Property(x => x.VaultPath).HasMaxLength(512).IsRequired();
            e.Property(x => x.Realm).HasMaxLength(128).IsRequired();
            e.Property(x => x.Kid).HasMaxLength(128).IsRequired();
        });
        b.Entity<KeyHistoryEntity>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => new { x.Realm, x.Kid, x.OccurredAt });
        });
        b.Entity<RotationOperationEntity>(e =>
        {
            e.HasKey(x => x.OperationId);
            e.HasIndex(x => new { x.Realm, x.IdempotencyKey }).IsUnique();
        });
        b.Entity<ScopeDefinitionEntity>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => x.Key).IsUnique();
            e.Property(x => x.Key).HasMaxLength(64).IsRequired();
            e.Property(x => x.DisplayName).HasMaxLength(128).IsRequired();
            e.Property(x => x.ValueType).HasMaxLength(32).IsRequired();
        });
        b.Entity<ApplicationResourceEntity>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => x.Key).IsUnique();
            e.Property(x => x.Key).HasMaxLength(64).IsRequired();
            e.Property(x => x.DisplayName).HasMaxLength(128).IsRequired();
        });
        b.Entity<ScopeResourceMappingEntity>(e =>
        {
            e.HasKey(x => new { x.ScopeDefinitionId, x.ApplicationResourceId });
            e.HasOne<ScopeDefinitionEntity>().WithMany().HasForeignKey(x => x.ScopeDefinitionId).OnDelete(DeleteBehavior.Cascade);
            e.HasOne<ApplicationResourceEntity>().WithMany().HasForeignKey(x => x.ApplicationResourceId).OnDelete(DeleteBehavior.Cascade);
        });
        b.Entity<RoleAllowedScopeEntity>(e =>
        {
            e.HasKey(x => new { x.RoleName, x.ScopeDefinitionId });
            e.Property(x => x.RoleName).HasMaxLength(128).IsRequired();
            e.HasOne<ScopeDefinitionEntity>().WithMany().HasForeignKey(x => x.ScopeDefinitionId).OnDelete(DeleteBehavior.Cascade);
        });
        b.Entity<UserRoleAssignmentEntity>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => new { x.UserId, x.RoleName }).IsUnique();
            e.HasIndex(x => x.UserId);
            e.Property(x => x.UserId).HasMaxLength(64).IsRequired();
            e.Property(x => x.RoleName).HasMaxLength(128).IsRequired();
        });
        b.Entity<AssignmentScopeEntity>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => new { x.UserRoleAssignmentId, x.ScopeDefinitionId }).IsUnique();
            e.HasOne<UserRoleAssignmentEntity>().WithMany().HasForeignKey(x => x.UserRoleAssignmentId).OnDelete(DeleteBehavior.Cascade);
            e.HasOne<ScopeDefinitionEntity>().WithMany().HasForeignKey(x => x.ScopeDefinitionId).OnDelete(DeleteBehavior.Restrict);
        });
        b.Entity<AssignmentScopeValueEntity>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => new { x.AssignmentScopeId, x.Value }).IsUnique();
            e.HasIndex(x => x.AssignmentScopeId);
            e.Property(x => x.Value).HasMaxLength(256).IsRequired();
            e.HasOne<AssignmentScopeEntity>().WithMany().HasForeignKey(x => x.AssignmentScopeId).OnDelete(DeleteBehavior.Cascade);
        });
    }

    public static void ConfigureProvider(DbContextOptionsBuilder b, string provider, string cs)
    {
        switch (provider.ToLowerInvariant())
        {
            case "oracle": b.UseOracle(cs); break;
            case "npgsql":
            case "postgres":
            case "postgresql": b.UseNpgsql(cs); break;
            default: b.UseSqlite(cs); break;
        }
    }
}

public sealed class EfKeyLifecycleRepository(KeyMetadataDbContext db) : IKeyLifecycleRepository
{
    public async Task<SigningKeyMetadata?> GetAsync(string realm, string kid, CancellationToken ct)
    {
        var e = await db.SigningKeys.FindAsync([realm, kid], ct);
        return e is null ? null : Map(e);
    }

    public async Task<IReadOnlyCollection<SigningKeyMetadata>> ListAsync(string realm, int page, int pageSize,
        CancellationToken ct)
    {
        var list = await db.SigningKeys.Where(x => x.Realm == realm).OrderBy(x => x.Kid)
            .Skip((page - 1) * pageSize).Take(pageSize).ToListAsync(ct);
        return list.Select(Map).ToList();
    }

    public Task<int> CountAsync(string realm, CancellationToken ct) =>
        db.SigningKeys.CountAsync(x => x.Realm == realm, ct);

    public async Task UpsertAsync(SigningKeyMetadata meta, CancellationToken ct)
    {
        var e = await db.SigningKeys.FindAsync([meta.Realm, meta.Kid], ct);
        if (e is null) db.SigningKeys.Add(ToEntity(meta));
        else UpdateEntity(e, meta);
        await db.SaveChangesAsync(ct);
    }

    public async Task AddHistoryAsync(string realm, string kid, string fromState, string toState, DateTimeOffset when,
        string actor, string? reason, CancellationToken ct)
    {
        db.KeyHistories.Add(new KeyHistoryEntity
        {
            Realm = realm, Kid = kid, FromState = fromState, ToState = toState, OccurredAt = when, Actor = actor,
            Reason = reason
        });
        await db.SaveChangesAsync(ct);
    }

    public async Task<IReadOnlyCollection<KeyHistoryEntryDto>> GetHistoryAsync(string realm, string kid,
        CancellationToken ct)
    {
        var list = await db.KeyHistories.Where(x => x.Realm == realm && x.Kid == kid).OrderBy(x => x.OccurredAt)
            .ToListAsync(ct);
        return list.Select(x => new KeyHistoryEntryDto(x.Kid, x.FromState, x.ToState, x.OccurredAt, x.Actor, x.Reason))
            .ToList();
    }

    public async Task<KeyRotationOperation?> GetOperationAsync(string operationId, CancellationToken ct)
    {
        var e = await db.RotationOperations.FindAsync([operationId], ct);
        return e is null ? null : MapOp(e);
    }

    public async Task<KeyRotationOperation?> GetOperationByIdempotencyAsync(string realm, string idempotencyKey,
        CancellationToken ct)
    {
        var e = await db.RotationOperations.FirstOrDefaultAsync(
            x => x.Realm == realm && x.IdempotencyKey == idempotencyKey, ct);
        return e is null ? null : MapOp(e);
    }

    public async Task UpsertOperationAsync(KeyRotationOperation op, CancellationToken ct)
    {
        var e = await db.RotationOperations.FindAsync([op.OperationId], ct);
        if (e is null) db.RotationOperations.Add(ToEntity(op));
        else UpdateEntity(e, op);
        await db.SaveChangesAsync(ct);
    }

    public async Task<IReadOnlyCollection<KeyRotationOperation>> ListInFlightAsync(string realm, CancellationToken ct)
    {
        var list = await db.RotationOperations
            .Where(x => x.Realm == realm && x.Status == SagaStatus.InProgress.ToString()).ToListAsync(ct);
        return list.Select(MapOp).ToList();
    }

    private static SigningKeyMetadata Map(SigningKeyEntity e) => new(e.Kid, (RsaKeySize)e.Size, e.PublicPemFingerprint,
        e.VaultPath, e.VaultVersion, Enum.Parse<KeyLifecycleState>(e.State), e.CreatedAt, e.Realm,
        e.KeycloakComponentId, e.ActivatedAt, e.PassivatedAt, e.RetiredAt, e.DestroyedAt, e.Origin);

    private static SigningKeyEntity ToEntity(SigningKeyMetadata m) => new()
    {
        Kid = m.Kid, Realm = m.Realm, Size = (int)m.Size, PublicPemFingerprint = m.PublicPemFingerprint,
        VaultPath = m.VaultPath, VaultVersion = m.VaultVersion, State = m.State.ToString(), CreatedAt = m.CreatedAt,
        KeycloakComponentId = m.KeycloakComponentId, ActivatedAt = m.ActivatedAt, PassivatedAt = m.PassivatedAt,
        RetiredAt = m.RetiredAt, DestroyedAt = m.DestroyedAt, Origin = m.Origin
    };

    private static void UpdateEntity(SigningKeyEntity e, SigningKeyMetadata m)
    {
        e.Size = (int)m.Size;
        e.PublicPemFingerprint = m.PublicPemFingerprint;
        e.VaultPath = m.VaultPath;
        e.VaultVersion = m.VaultVersion;
        e.State = m.State.ToString();
        e.KeycloakComponentId = m.KeycloakComponentId;
        e.ActivatedAt = m.ActivatedAt;
        e.PassivatedAt = m.PassivatedAt;
        e.RetiredAt = m.RetiredAt;
        e.DestroyedAt = m.DestroyedAt;
        e.Origin = m.Origin;
    }

    private static KeyRotationOperation MapOp(RotationOperationEntity e) => new(e.OperationId, e.IdempotencyKey,
        e.Realm, e.TargetKid, e.PreviousKid, Enum.Parse<KeyLifecycleState>(e.CurrentStep),
        Enum.Parse<SagaStatus>(e.Status), e.StartedAt, e.UpdatedAt, e.Actor, e.FailureReason, e.LockOwnerToken);

    private static RotationOperationEntity ToEntity(KeyRotationOperation o) => new()
    {
        OperationId = o.OperationId, IdempotencyKey = o.IdempotencyKey, Realm = o.Realm, TargetKid = o.TargetKid,
        PreviousKid = o.PreviousKid, CurrentStep = o.CurrentStep.ToString(), Status = o.Status.ToString(),
        StartedAt = o.StartedAt, UpdatedAt = o.UpdatedAt, Actor = o.Actor, FailureReason = o.FailureReason,
        LockOwnerToken = o.LockOwnerToken
    };

    private static void UpdateEntity(RotationOperationEntity e, KeyRotationOperation o)
    {
        e.IdempotencyKey = o.IdempotencyKey;
        e.TargetKid = o.TargetKid;
        e.PreviousKid = o.PreviousKid;
        e.CurrentStep = o.CurrentStep.ToString();
        e.Status = o.Status.ToString();
        e.UpdatedAt = o.UpdatedAt;
        e.FailureReason = o.FailureReason;
        e.LockOwnerToken = o.LockOwnerToken;
    }
}

namespace Identity.Contracts;

/// <summary>
/// Central constants for the namespaced scoped-access attribute and claim.
/// Attribute is the Keycloak user-attribute key; claim is the JWT claim consumers read.
/// </summary>
public static class ScopedAccessConstants
{
    public const string AttributeName = "iam.scoped_access";
    public const string ClaimName = "iam_access";
    public const int MaxInlineClaimBytes = 4096;
}

/// <summary>
/// A single role bound to arbitrary scope dimensions. Scope keys are dynamic (region, branch, …)
/// and require no schema change to introduce a new key.
/// </summary>
public sealed record ScopedRoleAssignment(
    string Role,
    IReadOnlyDictionary<string, IReadOnlyCollection<string>> Scopes);

/// <summary>
/// The full set of scoped assignments for a user. Serialized as a JSON array of
/// <see cref="ScopedRoleAssignment"/> and stored in the single Keycloak attribute
/// <see cref="ScopedAccessConstants.AttributeName"/>.
/// </summary>
public sealed record ScopedAccessDocument(
    IReadOnlyCollection<ScopedRoleAssignment> Assignments)
{
    public static ScopedAccessDocument Empty { get; } = new(Array.Empty<ScopedRoleAssignment>());
}

// ── User management DTOs ────────────────────────────────────────────────────

public sealed record CreateUserRequest(
    string Username,
    string? Email,
    string? FirstName,
    string? LastName,
    bool Enabled,
    CredentialRequest? Credentials,
    IReadOnlyCollection<ScopedRoleAssignmentDto>? Assignments);

public sealed record UpdateUserRequest(
    string? Email,
    string? FirstName,
    string? LastName,
    bool? Enabled);

public sealed record CredentialRequest(
    string Password,
    bool Temporary);

public sealed record ScopedRoleAssignmentDto(
    string Role,
    [property: System.Text.Json.Serialization.JsonConverter(typeof(ScopeDictionaryConverter))]
    IReadOnlyDictionary<string, IReadOnlyCollection<string>> Scopes);

// ── Scoped-access management DTOs ──────────────────────────────────────────

public sealed record SetScopedAccessRequest(
    IReadOnlyCollection<ScopedRoleAssignmentDto> Assignments);

public sealed record ScopedAccessResponse(
    string UserId,
    IReadOnlyCollection<ScopedRoleAssignment> Assignments);

// ── Business role DTOs ──────────────────────────────────────────────────────

public sealed record BusinessRoleDto(
    string Name,
    string? Description,
    bool Composite,
    IReadOnlyCollection<string> Permissions);

public sealed record CreateBusinessRoleRequest(
    string Name,
    string? Description,
    IReadOnlyCollection<string>? Permissions);

public sealed record UpdateBusinessRoleRequest(
    string? Description);

public sealed record AssignPermissionsRequest(
    IReadOnlyCollection<string> Permissions);

public sealed record EffectivePermissionsResponse(
    string Role,
    IReadOnlyCollection<string> Permissions);

public sealed record AccessContextResponse(
    string? UserId,
    string? Username,
    IReadOnlyCollection<string> Permissions,
    IReadOnlyCollection<ScopedRoleAssignment> Assignments);

using System.Text.Json;
using System.Text.Json.Serialization;

namespace Identity.Contracts;

/// <summary>
/// Accepts both "key": "single" and "key": ["a","b"] and normalizes to IReadOnlyCollection&lt;string&gt;.
/// Always writes as array.
/// </summary>
public sealed class ScopeDictionaryConverter : JsonConverter<IReadOnlyDictionary<string, IReadOnlyCollection<string>>>
{
    public override IReadOnlyDictionary<string, IReadOnlyCollection<string>> Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType == JsonTokenType.Null) return new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.Ordinal);
        if (reader.TokenType != JsonTokenType.StartObject) throw new JsonException("Scopes must be an object.");
        var dict = new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.Ordinal);
        while (reader.Read())
        {
            if (reader.TokenType == JsonTokenType.EndObject) break;
            if (reader.TokenType != JsonTokenType.PropertyName) throw new JsonException("Expected property name.");
            var key = reader.GetString() ?? string.Empty;
            reader.Read();
            IReadOnlyCollection<string> values;
            if (reader.TokenType == JsonTokenType.String)
            {
                var s = reader.GetString();
                values = string.IsNullOrWhiteSpace(s) ? Array.Empty<string>() : new[] { s!.Trim() };
            }
            else if (reader.TokenType == JsonTokenType.StartArray)
            {
                var list = new List<string>();
                while (reader.Read() && reader.TokenType != JsonTokenType.EndArray)
                {
                    if (reader.TokenType == JsonTokenType.String)
                    {
                        var s = reader.GetString();
                        if (!string.IsNullOrWhiteSpace(s)) list.Add(s!.Trim());
                    }
                    else if (reader.TokenType == JsonTokenType.Null) { }
                    else throw new JsonException($"Scope values must be strings. Path: {key}");
                }
                values = list.Distinct(StringComparer.Ordinal).OrderBy(v => v, StringComparer.Ordinal).ToArray();
            }
            else if (reader.TokenType == JsonTokenType.Null)
            {
                values = Array.Empty<string>();
            }
            else throw new JsonException($"Scope values must be a string or array of strings. Path: {key}");

            var trimmedKey = key.Trim();
            if (!string.IsNullOrWhiteSpace(trimmedKey))
                dict[trimmedKey] = values;
        }
        return dict;
    }

    public override void Write(Utf8JsonWriter writer, IReadOnlyDictionary<string, IReadOnlyCollection<string>> value, JsonSerializerOptions options)
    {
        writer.WriteStartObject();
        foreach (var kv in value.OrderBy(k => k.Key, StringComparer.Ordinal))
        {
            writer.WritePropertyName(kv.Key);
            writer.WriteStartArray();
            foreach (var v in kv.Value) writer.WriteStringValue(v);
            writer.WriteEndArray();
        }
        writer.WriteEndObject();
    }
}

using System.Security.Claims;
using Identity.Contracts;

namespace Company.Identity.Authorization;

/// <summary>
/// Reusable access-context abstraction for microservices. Provides EF-Core-friendly primitives.
/// Centralizes parsing of the compact <c>iam_access</c> claim so business code never touches raw claim values.
/// </summary>
/// <remarks>
/// Permission checks and <see cref="GetScopeValues"/> may depend on the <c>iam_access</c> claim, which is
/// omitted from oversized tokens (see <see cref="ScopedAccessConstants.MaxInlineClaimBytes"/>). Callers that
/// may run against a token whose claim was dropped should <see cref="EnsureLoadedAsync"/> once per request to
/// lazily resolve the authoritative assignment set from the Identity Facade; when the claim is present the
/// call is a no-op and no HTTP round-trip happens.
/// </remarks>
public interface ICurrentAccessContext
{
    IReadOnlyCollection<ScopedRoleAssignment> GetAssignments();
    bool HasPermission(string permission);
    bool HasPermission(string permission, string scopeKey, string scopeValue);
    IReadOnlyCollection<string> GetScopeValues(string scopeKey);
    bool HasScope(string scopeKey, string scopeValue);

    /// <summary>
    /// Resolves scoped assignments from the facade when they could not be read from the token claim.
    /// Idempotent; safe to call on every request. No-op when assignments came from the claim.
    /// </summary>
    Task EnsureLoadedAsync(CancellationToken ct = default);
}

/// <summary>
/// Static, claims-only access context. Reads permissions from the standard <c>permission</c>/
/// <c>permissions</c>/role claims and scoped assignments from <c>iam_access</c>. Does not perform
/// facade resolution — <see cref="EnsureLoadedAsync"/> is a completed no-op. Used directly by unit
/// tests and as the building block behind <c>FacadeResolvingAccessContext</c>.
/// </summary>
public sealed class ClaimsPrincipalAccessContext : ICurrentAccessContext
{
    private readonly IReadOnlyCollection<string> _permissions;
    private readonly IReadOnlyCollection<ScopedRoleAssignment> _assignments;
    private readonly IReadOnlyDictionary<string, HashSet<string>> _scopeIndex;

    public ClaimsPrincipalAccessContext(ClaimsPrincipal principal)
    {
        _permissions = principal.FindAll("permission")
            .Concat(principal.FindAll("permissions"))
            .Select(c => c.Value)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        // Also include role claims as permissions for compatibility
        var roles = principal.FindAll(ClaimTypes.Role).Concat(principal.FindAll("role")).Select(c => c.Value);
        _permissions = _permissions.Concat(roles).Distinct(StringComparer.Ordinal).ToArray();

        _assignments = ParseAssignments(principal);
        _scopeIndex = BuildScopeIndex(_assignments);
    }

    // Internal ctor used by FacadeResolvingAccessContext after a facade round-trip.
    internal ClaimsPrincipalAccessContext(
        IReadOnlyCollection<string> permissions,
        IReadOnlyCollection<ScopedRoleAssignment> assignments)
    {
        _permissions = permissions;
        _assignments = assignments;
        _scopeIndex = BuildScopeIndex(assignments);
    }

    /// <summary>True when the assignments were carried by the token claim (no facade resolution needed).</summary>
    internal bool HasInlineAssignments => _assignments.Count > 0;

    internal IReadOnlyCollection<string> Permissions => _permissions;

    public IReadOnlyCollection<ScopedRoleAssignment> GetAssignments() => _assignments;

    public bool HasPermission(string permission)
        => _permissions.Contains(permission, StringComparer.Ordinal);

    public bool HasPermission(string permission, string scopeKey, string scopeValue)
    {
        if (!HasPermission(permission)) return false;
        return HasScope(scopeKey, scopeValue);
    }

    public IReadOnlyCollection<string> GetScopeValues(string scopeKey)
        => _scopeIndex.TryGetValue(scopeKey, out var set)
            ? set.ToArray()
            : Array.Empty<string>();

    public bool HasScope(string scopeKey, string scopeValue)
        => _scopeIndex.TryGetValue(scopeKey, out var set) && set.Contains(scopeValue);

    // Static context never resolves from the facade; the claims are all there is.
    public Task EnsureLoadedAsync(CancellationToken ct = default) => Task.CompletedTask;

    private static IReadOnlyDictionary<string, HashSet<string>> BuildScopeIndex(
        IReadOnlyCollection<ScopedRoleAssignment> assignments)
    {
        var index = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var a in assignments)
        foreach (var kv in a.Scopes)
        {
            if (!index.TryGetValue(kv.Key, out var set))
            {
                set = new HashSet<string>(StringComparer.Ordinal);
                index[kv.Key] = set;
            }
            foreach (var v in kv.Value) set.Add(v);
        }
        return index;
    }

    private static IReadOnlyCollection<ScopedRoleAssignment> ParseAssignments(ClaimsPrincipal principal)
    {
        var claimValues = principal.FindAll(ScopedAccessConstants.ClaimName).Select(c => c.Value).ToArray();
        if (claimValues.Length == 0) return Array.Empty<ScopedRoleAssignment>();

        // The claim may be a single JSON array string or multiple string claims.
        // Try single-value JSON array first.
        var combined = claimValues.Length == 1 ? claimValues[0] : string.Join("", claimValues);
        if (string.IsNullOrWhiteSpace(combined)) return Array.Empty<ScopedRoleAssignment>();

        try
        {
            var doc = System.Text.Json.JsonDocument.Parse(combined);
            if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
            {
                return System.Text.Json.JsonSerializer.Deserialize<ScopedRoleAssignment[]>(
                    combined,
                    new System.Text.Json.JsonSerializerOptions { PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase })
                    ?.Where(a => !string.IsNullOrWhiteSpace(a.Role))
                    .Select(a => new ScopedRoleAssignment(
                        a.Role.Trim(),
                        NormalizeScopes(a.Scopes)))
                    .ToArray() ?? Array.Empty<ScopedRoleAssignment>();
            }
        }
        catch { }

        return Array.Empty<ScopedRoleAssignment>();
    }

    private static IReadOnlyDictionary<string, IReadOnlyCollection<string>> NormalizeScopes(
        IReadOnlyDictionary<string, IReadOnlyCollection<string>>? scopes)
    {
        if (scopes is null || scopes.Count == 0)
            return new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.Ordinal);
        var result = new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.Ordinal);
        foreach (var kv in scopes)
        {
            var key = kv.Key?.Trim();
            if (string.IsNullOrWhiteSpace(key)) continue;
            var values = kv.Value?.Where(v => !string.IsNullOrWhiteSpace(v))
                .Select(v => v.Trim())
                .Distinct(StringComparer.Ordinal)
                .ToArray() ?? Array.Empty<string>();
            if (values.Length == 0) continue;
            result[key!] = values;
        }
        return result;
    }
}

