using System.Collections.Concurrent;
using Identity.Persistence.KeyManagement;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

namespace Identity.Application.Scope;

// ── Value validators ─────────────────────────────────────────────
public interface IScopeValueValidator
{
    string ScopeKey { get; } // "*" = default
    bool IsValid(string value, out string? error);
}

public sealed class DefaultScopeValueValidator : IScopeValueValidator
{
    public string ScopeKey => "*";
    public bool IsValid(string value, out string? error)
    {
        if (string.IsNullOrWhiteSpace(value)) { error = "Scope value must not be empty."; return false; }
        if (value.Length > 256) { error = "Scope value exceeds 256 characters."; return false; }
        error = null; return true;
    }
}

public interface IScopeValueValidatorRegistry
{
    IScopeValueValidator GetValidator(string scopeKey);
}

public sealed class ScopeValueValidatorRegistry(IEnumerable<IScopeValueValidator> validators) : IScopeValueValidatorRegistry
{
    private readonly Dictionary<string, IScopeValueValidator> _map = validators
        .GroupBy(v => v.ScopeKey, StringComparer.OrdinalIgnoreCase)
        .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);
    public IScopeValueValidator GetValidator(string scopeKey)
        => _map.TryGetValue(scopeKey, out var v) ? v : _map.TryGetValue("*", out var d) ? d : new DefaultScopeValueValidator();
}

// ── Scope definition / resource services with cache ─────────────
public interface IScopeCacheInvalidator { void Invalidate(); }

public sealed class ScopeRegistryService(KeyMetadataDbContext db, IMemoryCache cache, ILogger<ScopeRegistryService> logger) : IScopeCacheInvalidator
{
    private const string ActiveScopesKey = "scopes:active";
    private const string ResourceMapKey = "scopes:resourceMap";
    private const string RoleAllowedKey = "scopes:roleAllowed";
    private static readonly TimeSpan Ttl = TimeSpan.FromMinutes(5);

    public void Invalidate()
    {
        cache.Remove(ActiveScopesKey); cache.Remove(ResourceMapKey); cache.Remove(RoleAllowedKey);
    }

    public async Task<IReadOnlyCollection<ScopeDefinitionEntity>> GetActiveScopesAsync(CancellationToken ct)
    {
        if (cache.TryGetValue(ActiveScopesKey, out IReadOnlyCollection<ScopeDefinitionEntity>? cached) && cached is not null) return cached;
        var list = await db.ScopeDefinitions.Where(s => s.IsActive).ToListAsync(ct);
        cache.Set(ActiveScopesKey, (IReadOnlyCollection<ScopeDefinitionEntity>)list, Ttl);
        return list;
    }

    public async Task<ScopeDefinitionEntity?> GetByKeyAsync(string key, CancellationToken ct)
    {
        var all = await GetActiveScopesAsync(ct);
        var found = all.FirstOrDefault(s => string.Equals(s.Key, key, StringComparison.OrdinalIgnoreCase));
        if (found is not null) return found;
        // also check inactive to give precise error
        return await db.ScopeDefinitions.FirstOrDefaultAsync(s => s.Key.ToLower() == key.ToLower(), ct);
    }

    public async Task<Dictionary<string, HashSet<string>>> GetScopesForResourceMapAsync(CancellationToken ct)
    {
        if (cache.TryGetValue(ResourceMapKey, out Dictionary<string, HashSet<string>>? cached) && cached is not null) return cached;
        var mappings = await (from m in db.ScopeResourceMappings
                              join s in db.ScopeDefinitions on m.ScopeDefinitionId equals s.Id
                              join r in db.ApplicationResources on m.ApplicationResourceId equals r.Id
                              select new { ResourceKey = r.Key, ScopeKey = s.Key }).ToListAsync(ct);
        var map = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        foreach (var x in mappings)
        {
            if (!map.TryGetValue(x.ResourceKey, out var set)) { set = new HashSet<string>(StringComparer.OrdinalIgnoreCase); map[x.ResourceKey] = set; }
            set.Add(x.ScopeKey);
        }
        cache.Set(ResourceMapKey, map, Ttl);
        return map;
    }

    public async Task<HashSet<string>> GetAllowedScopesForRoleAsync(string role, CancellationToken ct)
    {
        var all = await GetRoleAllowedMapAsync(ct);
        return all.TryGetValue(role, out var set) ? set : new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    }

    public async Task<bool> IsScopeAllowedForRoleAsync(string role, string scopeKey, CancellationToken ct)
    {
        var map = await GetRoleAllowedMapAsync(ct);
        if (!map.TryGetValue(role, out var allowed)) return true; // permissive if no restriction configured for role
        if (allowed.Count == 0) return true;
        return allowed.Contains(scopeKey);
    }

    private async Task<Dictionary<string, HashSet<string>>> GetRoleAllowedMapAsync(CancellationToken ct)
    {
        if (cache.TryGetValue(RoleAllowedKey, out Dictionary<string, HashSet<string>>? cached) && cached is not null) return cached;
        var rows = await (from ra in db.RoleAllowedScopes
                          join s in db.ScopeDefinitions on ra.ScopeDefinitionId equals s.Id
                          select new { ra.RoleName, ScopeKey = s.Key }).ToListAsync(ct);
        var map = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        foreach (var r in rows)
        {
            if (!map.TryGetValue(r.RoleName, out var set)) { set = new HashSet<string>(StringComparer.OrdinalIgnoreCase); map[r.RoleName] = set; }
            set.Add(r.ScopeKey);
        }
        cache.Set(RoleAllowedKey, map, Ttl);
        return map;
    }
}

// ── Assignment validator ─────────────────────────────────────────
public sealed class ScopeAssignmentValidator(ScopeRegistryService registry, IScopeValueValidatorRegistry validators)
{
    public async Task<Dictionary<string, string[]>> ValidateAsync(IEnumerable<Identity.Contracts.ScopedRoleAssignmentDto> assignments, IBusinessRoleStore roles, CancellationToken ct)
    {
        var errors = new Dictionary<string, string[]>();
        int idx = 0;
        foreach (var a in assignments)
        {
            var roleExists = await roles.GetAsync(a.Role, ct);
            if (roleExists is null)
                AddError(errors, $"assignments[{idx}].role", $"Role '{a.Role}' does not exist.");

            foreach (var kv in a.Scopes)
            {
                var scopeKey = kv.Key;
                var def = await registry.GetByKeyAsync(scopeKey, ct);
                if (def is null || !def.IsActive)
                {
                    AddError(errors, $"assignments[{idx}].scopes.{scopeKey}", $"Scope '{scopeKey}' is not defined or is inactive.");
                    continue;
                }
                if (!await registry.IsScopeAllowedForRoleAsync(a.Role, scopeKey, ct))
                    AddError(errors, $"assignments[{idx}].scopes.{scopeKey}", $"Scope '{scopeKey}' is not allowed for role '{a.Role}'.");

                var validator = validators.GetValidator(scopeKey);
                foreach (var v in kv.Value)
                {
                    if (!validator.IsValid(v, out var err))
                        AddError(errors, $"assignments[{idx}].scopes.{scopeKey}", err ?? "Invalid scope value.");
                }
                if (kv.Value.Count == 0)
                    AddError(errors, $"assignments[{idx}].scopes.{scopeKey}", "Scope must have at least one value.");
            }
            idx++;
        }
        return errors;
    }

    private static void AddError(Dictionary<string,string[]> d, string key, string msg)
    {
        if (d.TryGetValue(key, out var arr)) d[key] = arr.Append(msg).ToArray();
        else d[key] = new[] { msg };
    }
}
