    {
        var assignments = await db.UserRoleAssignments.Where(a => a.UserId == userId).ToListAsync(ct);
        if (assignments.Count == 0) return ScopedAccessDocument.Empty;
        var ids = assignments.Select(a => a.Id).ToArray();
        var scopes = await db.AssignmentScopes.Where(s => ids.Contains(s.UserRoleAssignmentId)).ToListAsync(ct);
        var scopeIds = scopes.Select(s => s.Id).ToArray();
        var values = scopeIds.Length == 0 ? new List<AssignmentScopeValueEntity>()
            : await db.AssignmentScopeValues.Where(v => scopeIds.Contains(v.AssignmentScopeId)).ToListAsync(ct);
        var scopeDefMap = await db.ScopeDefinitions.ToDictionaryAsync(s => s.Id, s => s.Key, ct);

        var byAssignment = new Dictionary<Guid, Dictionary<string, List<string>>>();
        foreach (var s in scopes)
        {
            if (!scopeDefMap.TryGetValue(s.ScopeDefinitionId, out var key)) continue;
            if (!byAssignment.TryGetValue(s.UserRoleAssignmentId, out var dict))
            {
                dict = new Dictionary<string, List<string>>(StringComparer.Ordinal);
                byAssignment[s.UserRoleAssignmentId] = dict;
            }
            var vals = values.Where(v => v.AssignmentScopeId == s.Id).Select(v => v.Value).ToList();
            dict[key] = vals;
        }

        var result = assignments.Select(a =>
        {
            byAssignment.TryGetValue(a.Id, out var dict);
            var scopesDict = (IReadOnlyDictionary<string, IReadOnlyCollection<string>>)
                (dict is null ? new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.Ordinal)
                : dict.ToDictionary(k => k.Key, v => (IReadOnlyCollection<string>)v.Value.ToArray(), StringComparer.Ordinal));
            return new ScopedRoleAssignment(a.RoleName, scopesDict);
        }).OrderBy(a => a.Role, StringComparer.Ordinal).ToArray();
        return new ScopedAccessDocument(result);
    }

    public async Task<IReadOnlyDictionary<string, IReadOnlyCollection<string>>> GetEffectiveScopesAsync(string userId, CancellationToken ct)
    {
        var doc = await GetAsync(userId, ct);
        var merged = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var a in doc.Assignments)
            foreach (var kv in a.Scopes)
            {
                if (!merged.TryGetValue(kv.Key, out var set)) { set = new HashSet<string>(StringComparer.Ordinal); merged[kv.Key] = set; }
                foreach (var v in kv.Value) set.Add(v);
            }
        return merged.ToDictionary(k => k.Key, v => (IReadOnlyCollection<string>)v.Value.ToArray(), StringComparer.Ordinal);
    }

    public async Task SetAsync(string userId, IReadOnlyCollection<ScopedRoleAssignmentDto> assignments, CancellationToken ct)
    {
        var existing = await db.UserRoleAssignments.Where(a => a.UserId == userId).ToListAsync(ct);
        var existingIds = existing.Select(a => a.Id).ToArray();
        if (existingIds.Length > 0)
        {
            var scopes = await db.AssignmentScopes.Where(s => existingIds.Contains(s.UserRoleAssignmentId)).ToListAsync(ct);
            var scopeIds = scopes.Select(s => s.Id).ToArray();
            if (scopeIds.Length > 0)
            {
                var vals = await db.AssignmentScopeValues.Where(v => scopeIds.Contains(v.AssignmentScopeId)).ToListAsync(ct);
                db.AssignmentScopeValues.RemoveRange(vals);
            }
            db.AssignmentScopes.RemoveRange(scopes);
            db.UserRoleAssignments.RemoveRange(existing);
            await db.SaveChangesAsync(ct);
        }
        if (assignments.Count == 0) return;
        var scopeDefs = await db.ScopeDefinitions.ToDictionaryAsync(s => s.Key, s => s.Id, StringComparer.OrdinalIgnoreCase, ct);
        foreach (var a in assignments)
        {
            var ura = new UserRoleAssignmentEntity { Id = Guid.NewGuid(), UserId = userId, RoleName = a.Role.Trim(), AssignedAt = DateTimeOffset.UtcNow };
            db.UserRoleAssignments.Add(ura);
