        var errors = await validator.ValidateAsync([new ScopedRoleAssignmentDto("R", new Dictionary<string, IReadOnlyCollection<string>> { ["branch"] = ["b-1"] })], new FakeRoleStore("R"), CancellationToken.None);
        Assert.NotEmpty(errors);
    }

