118	builder.Services.AddOpenApi("v1", o =>
119	{
120	    o.AddDocumentTransformer((document, _, _) =>
121	    {
122	        document.Info.Title = "Identity Facade";
123	        document.Info.Description =
124	            "Keycloak-centric facade — auth proxy, directory, permissions, key lifecycle. " +
125	            "Present a Keycloak-issued JWT via the Bearer scheme below; privileged groups need the " +
126	            "matching Identity.* permission claims (e.g. Identity.Keys.Generate for key admin routes).";
127	        var bearer = new Microsoft.OpenApi.OpenApiSecurityScheme
128	        {
129	            Type = Microsoft.OpenApi.SecuritySchemeType.Http,
130	            Scheme = "bearer",
131	            BearerFormat = "JWT",
132	            Description = "Keycloak-issued JWT"
133	        };
134	        var components = document.Components ?? new Microsoft.OpenApi.OpenApiComponents();
135	        document.Components = components;
136	        components.SecuritySchemes ??= new Dictionary<string, Microsoft.OpenApi.IOpenApiSecurityScheme>();
137	        components.SecuritySchemes["Bearer"] = bearer;
138	        document.Security =
139	        [
140	            new Microsoft.OpenApi.OpenApiSecurityRequirement
141	            {
142	                [new Microsoft.OpenApi.OpenApiSecuritySchemeReference("Bearer", document)] = []
143	            }
144	        ];
145	        return Task.CompletedTask;
146	    });
147	});
148	
149	var app = builder.Build();
150	if (app.Environment.IsDevelopment())
151	{
152	    // Scalar reads the Microsoft.OpenApi document at /openapi/v1.json — full interactive UI
153	    // with "Try it" requests against every REST group.
154	    app.MapScalarApiReference(options => options
155	        .WithTitle("Identity Facade")
156	        .WithOpenApiRoutePattern("/openapi/v1.json")
157	        .AddPreferredSecuritySchemes(["Bearer"]));
158	}
159	
160	app.MapOpenApi();
161	// No HTTPS endpoint exists in Development/compose (plain HTTP on 5080), so a redirect here would 307 every request.
162	if (!app.Environment.IsDevelopment()) app.UseHttpsRedirection();
163	app.UseAuthentication();
164	app.UseAuthorization();
165	app.MapHealthChecks("/health/live");
166	app.MapOidcProxy();
167	app.MapGet("/api/identity/me", (ICurrentUserContext current) =>
168	        current.UserId is null
169	            ? Results.Unauthorized()
170	            : Results.Ok(
171	                new { current.UserId, current.Username, current.Roles, current.Permissions, current.SessionId }))
172	    .RequireAuthorization()
173	    .WithTags("Users")
174	    .WithName("Me")
175	    .Produces<object>(200);
176	app.MapAuth();
177	app.MapUsers();
178	app.MapUserManagement();
179	app.MapBusinessRoles();
180	app.MapScopeAdmin();
181	app.MapAccessContext();
182	app.MapPermissions();
183	app.MapAdminKeys();
