185	app.MapGrpcService<Company.Identity.Grpc.KeyAdminGrpcService>();
186	// Seed facade-owned permissions through the existing registry so they are mirrored to Keycloak.
187	try
188	{
189	    using var scope = app.Services.CreateScope();
190	    var registrar = scope.ServiceProvider.GetRequiredService<Identity.Infrastructure.Keycloak.FacadePermissionRegistrar>();
191	    var asm = typeof(Program).Assembly;
192	    // Use a short timeout for seeding; don't block startup on Keycloak availability.
193	    using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(10));
194	    await registrar.RegisterAsync(asm, cts.Token);
195	}
196	catch { /* best-effort */ }
197	
198	try
199	{
200	    using var scope2 = app.Services.CreateScope();
201	    var mapper = scope2.ServiceProvider.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakIamAccessClaimMapper>();
202	    using var cts2 = new CancellationTokenSource(TimeSpan.FromSeconds(10));
203	    await mapper.EnsureAsync(cts2.Token);
204	}
205	catch { /* best-effort */ }
206	
207	try
208	{
209	    using var scope3 = app.Services.CreateScope();
210	    var db = scope3.ServiceProvider.GetRequiredService<Identity.Persistence.KeyManagement.KeyMetadataDbContext>();
211	    using var cts3 = new CancellationTokenSource(TimeSpan.FromSeconds(10));
212	    await Identity.Persistence.KeyManagement.ScopeSeed.EnsureSeededAsync(db, cts3.Token);
213	}
214	catch { /* best-effort */ }
215	
216	app.MapPost("/api/identity/external/organization-token",
217	        (OrganizationTokenRequest request) => Results.StatusCode(StatusCodes.Status501NotImplemented))
218	    .WithTags("Auth").WithName("ExchangeOrganizationToken");
219	app.Run();
