    {
        var list = await db.KeyHistories.Where(x => x.Realm == realm && x.Kid == kid).OrderBy(x => x.OccurredAt)
            .ToListAsync(ct);
        return list.Select(x => new KeyHistoryEntryDto(x.Kid, x.FromState, x.ToState, x.OccurredAt, x.Actor, x.Reason))
