        VaultPath = m.VaultPath, VaultVersion = m.VaultVersion, State = m.State.ToString(), CreatedAt = m.CreatedAt,
        KeycloakComponentId = m.KeycloakComponentId, ActivatedAt = m.ActivatedAt, PassivatedAt = m.PassivatedAt,
