1	using Company.Identity.Authentication.AspNetCore;
2	using Company.Identity.Authorization.AspNetCore;
3	using Identity.Api;
4	using Identity.Application;
5	using Identity.Contracts;
6	using Scalar.AspNetCore;
7	
8	var builder = WebApplication.CreateBuilder(args);
9	var authority = builder.Configuration["Identity:Authority"] ??
10	                throw new InvalidOperationException("Identity:Authority is required.");
11	var audience = builder.Configuration["Identity:Audience"] ?? string.Empty;
12	var requireHttpsMetadata = builder.Configuration["Identity:RequireHttpsMetadata"] ?? "false";
13	
14	builder.Services.AddSingleton(TimeProvider.System);
15	builder.Services.AddHttpContextAccessor();
16	builder.Services.AddHttpClient();
17	builder.Services.AddScoped<ICurrentUserContext, HttpCurrentUserContext>();
18	builder.Services.AddCompanyAuthentication(options =>
19	{
20	    options.Authority = authority;
21	    options.Audience = audience;
22	    options.RequireHttpsMetadata = bool.TryParse(requireHttpsMetadata, out var result) && result;
23	});
24	builder.Services.AddCompanyAuthorization();
25	builder.Services.AddGrpc();
26	
27	// Key management
28	builder.Services.Configure<KeyManagementOptions>(builder.Configuration.GetSection("Identity:KeyManagement"));
29	builder.Services.Configure<Identity.Infrastructure.Vault.VaultOptions>(
30	    builder.Configuration.GetSection("Identity:Vault"));
31	builder.Services.Configure<Identity.Infrastructure.Keycloak.KeycloakOptions>(
32	    builder.Configuration.GetSection("Identity:KeycloakAdmin"));
33	builder.Services.AddSingleton(sp =>
34	    sp.GetRequiredService<Microsoft.Extensions.Options.IOptions<KeyManagementOptions>>().Value);
35	builder.Services.AddSingleton<IKeyGenerationService, Identity.Infrastructure.RsaKeyGenerationService>();
36	builder.Services.AddScoped<IKeyRetirementSafety, Identity.Infrastructure.KeyRetirementSafety>();
37	builder.Services.AddSingleton<IKeyRotationLock, Identity.Infrastructure.Redis.InMemoryKeyRotationLock>();
38	builder.Services.AddSingleton<IAuditSink>(sp => new Identity.Infrastructure.NoopAuditSink());
39	builder.Services.AddHttpClient<Identity.Infrastructure.Vault.VaultSigningKeyStore>();
40	builder.Services.AddSingleton<ISigningKeyVault>(sp =>
41	    sp.GetRequiredService<Identity.Infrastructure.Vault.VaultSigningKeyStore>());
42	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakKeyManager>();
43	builder.Services.AddSingleton<IKeycloakKeyManager>(sp =>
44	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakKeyManager>());
45	
46	// Directory + permissions — Keycloak is source of truth; facade registry is in-memory so failure never blocks start.
47	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>();
48	builder.Services.AddSingleton<IUserDirectory>(sp =>
49	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>());
50	builder.Services.AddSingleton<IRoleDirectory>(sp =>
51	    sp.GetRequiredService<Identity.Infrastructure.Keycloak.KeycloakDirectoryAdapter>());
52	// Registered permissions are mirrored into Keycloak realm roles so they reach token claims
53	// through the existing oidc-usermodel-realm-role-mapper. Mirroring is best-effort and never
54	// blocks registration or startup.
55	builder.Services.AddHttpClient<Identity.Infrastructure.Keycloak.KeycloakRoleProvisioner>();
56	builder.Services.AddSingleton<IKeycloakRoleProvisioner>(sp =>
