public static class ScopeModelConfiguration
{
    public static void Configure(ModelBuilder b)
    {
        b.Entity<ScopeDefinitionEntity>(e =>
        {
            e.HasKey(x => x.Id);
            e.HasIndex(x => x.Key).IsUnique();
            e.Property(x => x.Key).HasMaxLength(64).IsRequired();
